  const dz = assets.design ? ` Item designs are used: put them in assets/designs/<id>.json; an item's full id is "${assets.namespace}:<id>" and a custom texture's item model is "${assets.namespace}:<texture name>".${assets.gameplay ? ` Menus and quests are designs in the same folder ("kind":"menu" / "quest"); NPC menus open on entities tagged ${assets.namespace}.npc.<menu id>.` : ""}${assets.bosses ? ` Bosses and encounters are designs in the same folder ("kind":"boss" / "encounter"); boss mobs carry the scoreboard tag ${assets.namespace}.boss.` : ""}${assets.hud ? ` HUDs are designs in the same folder ("kind":"hud"); their glyphs live in the font ${assets.namespace}:hud of this mod's pack.` : ""}` : "";
