// Cyrus plans: "how many mods or edits can I make with this?" (pure, client-safe, unit-tested).
//
// Computed ONLY from the live cost table the economy already uses, never from hardcoded counts:
//  - the reserve table (`cyrus_tok_reserve_table`, lib/cyrus/tokens/config.ts): per model and size,
//    [typical, high] tokens a build spends, measured from real builds (ECONOMY.md section 1);
//  - CHANGE_COST_FACTOR (lib/cyrus/estimate.ts): an edit costs about that share of a fresh build.
// A range is [tokens / high, tokens / typical], rounded so it never promises more than the table.
// The UI always labels it an estimate ("depends on size").
import { CHANGE_COST_FACTOR } from "../estimate";
import type { CyrusModelId } from "../models";
import type { ReserveTable } from "./config";

export type CountRange = [number, number];
export type PlanModelEstimate = {
  model: CyrusModelId;
  /** small mods ("simple": a command, a message, a drop table) */
  small: CountRange;
  /** typical mods ("standard": menus, saved data, an economy) */
  typical: CountRange;
  /** edits / refinements of a small mod */
  edits: CountRange;
};

/** Round a count down to something readable: exact below 20, then to 5s, then to 10s. */
export function niceDown(n: number): number {
  const v = Math.max(0, Math.floor(n));
  if (v < 20) return v;
  if (v < 100) return Math.floor(v / 5) * 5;
  return Math.floor(v / 10) * 10;
}

/** How many builds of a [typical, high] token range fit in `tokens`. */
export function countRange(tokens: number, range: readonly [number, number], factor = 1): CountRange {
  const lo = Math.max(1, range[0] * factor);
  const hi = Math.max(lo, range[1] * factor);
  const a = niceDown(tokens / hi);
  const b = niceDown(tokens / lo);
  return [Math.min(a, b), b];
}

export function planModelEstimate(tokens: number, model: CyrusModelId, reserve: ReserveTable): PlanModelEstimate {
  const t = reserve[model] ?? reserve.saka;
  return {
    model,
    small: countRange(tokens, t.simple),
    typical: countRange(tokens, t.standard),
    edits: countRange(tokens, t.simple, CHANGE_COST_FACTOR),
  };
}

/** Per unlocked model, best model first (a plan's headline is its top model). */
export function planEstimates(tokens: number, models: readonly CyrusModelId[], reserve: ReserveTable): PlanModelEstimate[] {
  const order: CyrusModelId[] = ["yakko", "saka", "katara"];
  return order.filter((m) => models.includes(m)).map((m) => planModelEstimate(tokens, m, reserve));
}

/** "20 to 35" / "4" / "less than 1". */
export function fmtCount([a, b]: CountRange): string {
  if (b <= 0) return "less than 1";
  if (a === b) return `${a}`;
  return `${a} to ${b}`;
}

/** One plain sentence, e.g. "about 10 to 25 small mods or 13 to 31 edits on Katara". */
export function planEstimateLine(e: PlanModelEstimate, modelName: string): string {
  return `about ${fmtCount(e.small)} small mods or ${fmtCount(e.edits)} edits on ${modelName}`;
}
// Cyrus token spend, read side: the live meter of a running build and the spend breakdown of a mod (every version,
// change and asset build of one project). Server only; reads the reservation + ledger the economy already writes.
//
// Honest numbers:
//  - "estimated": tokensForCost(the AI usage the builder has reported so far). It moves while the build runs and is
//    NOT a charge; the account only ever pays what settle decides.
//  - "settled": the ledger's settle row (charged, returned to the balance, and what Nxeon wrote off).
import type { Prisma } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { isCyrusModel, type CyrusModelId } from "../models";
import { readCyrusMeta } from "../meta";
import { loadTokenConfig, type TokenConfig } from "./config";
import { tokensForCost } from "./economy";

export type SpendState = "running" | "settling" | "settled" | "released" | "untracked";

export type BuildSpend = {
  buildId: string;
  model: CyrusModelId;
  state: SpendState;
  /** Tokens held when it started (0 = untracked or not reserved). */
  held: number;
  /** From the AI usage reported so far; an estimate, never a charge. */
  estimated: number;
  /** Final figures once settled (null while running). */
  charged: number | null;
  returned: number | null;
  writeoff: number;
  reason: string | null;
  settledAt: string | null;
  /** Live-test fix (B): where `estimated` comes from: "usage" = the builder's live per-turn usage; "stage" = no live
   *  usage yet, a clearly labelled estimate from the stage and the elapsed time; "final" = the build has ended. */
  estimateKind: "usage" | "stage" | "final";
  /** The build's stage (queued, planning, coding, compiling, repairing, scanning, succeeded, failed). */
  stage: string;
  /** Since the build was created (ms). */
  elapsedMs: number;
  /** Settled: charged more than it held (the extra came from the balance). Shown plainly, never hidden. */
  overHeld: boolean;
};

type Res = { amount: number; status: string; charged: number | null; model: string; settledAt: Date | null } | null;
type Build = { id: string; status: string; costUsd: number; cyrus: Prisma.JsonValue | null; result?: Prisma.JsonValue | null; createdAt?: Date | null };
type Settle = { delta: number; note: string | null; meta: Prisma.JsonValue | null; createdAt: Date } | null;

const TERMINAL = new Set(["succeeded", "failed"]);

/** Where a running build usually is, as a share of its total cost, per stage (from the measured builds' usage by stage). */
export const STAGE_SPAN: Readonly<Record<string, readonly [number, number]>> = {
  queued: [0, 0.02], planning: [0.03, 0.35], coding: [0.35, 0.8], compiling: [0.8, 0.88], repairing: [0.84, 0.95], scanning: [0.9, 0.97],
};
/** A typical build's wall time (measured avg 160 s; the first live Yakko build took 202 s). */
export const TYPICAL_BUILD_MS = 180_000;

/**
 * Live-test fix (B): the meter's "so far" figure. With the builder's live usage (service 0.6+) it is that usage in
 * tokens; without it (an older builder, or before the first turn reports) it is a STAGE estimate: the expected total
 * (the hold without its 20% headroom) times where the stage and the elapsed time put the build, never above the
 * stage's ceiling. Either way never below what was really reported so far.
 */
export function liveEstimate(b: Build, held: number, model: CyrusModelId, cfg: TokenConfig, now = Date.now()): { estimated: number; kind: BuildSpend["estimateKind"]; elapsedMs: number } {
  const live = (b.result as { live?: { costUsd?: unknown } } | null | undefined)?.live;
  const liveUsd = live && typeof live.costUsd === "number" ? live.costUsd : null;
  const reported = tokensForCost(Math.max(b.costUsd || 0, liveUsd ?? 0), model, cfg);
  const elapsedMs = b.createdAt ? Math.max(0, now - b.createdAt.getTime()) : 0;
  if (TERMINAL.has(b.status)) return { estimated: reported, kind: "final", elapsedMs };
  if (liveUsd !== null && liveUsd > (b.costUsd || 0) + 1e-6) return { estimated: reported, kind: "usage", elapsedMs };
  const span = STAGE_SPAN[b.status] ?? [0, 0.95];
  const expected = held > 0 ? held / 1.2 : 0;
  const frac = Math.min(span[1], Math.max(span[0], (elapsedMs / TYPICAL_BUILD_MS) * 0.95));
  return { estimated: Math.max(reported, Math.round(frac * expected)), kind: "stage", elapsedMs };
}

/** Pure: one build's spend from its rows. */
export function buildSpendFrom(b: Build, res: Res, settle: Settle, cfg: TokenConfig, now = Date.now()): BuildSpend {
  const model: CyrusModelId = res && isCyrusModel(res.model) ? res.model : (readCyrusMeta(b.cyrus).model ?? "saka");
  const le = liveEstimate(b, res?.amount ?? 0, model, cfg, now);
  const base = { estimated: le.estimated, estimateKind: le.kind, stage: b.status, elapsedMs: le.elapsedMs, overHeld: false };
  if (!res) return { buildId: b.id, model, state: "untracked", held: 0, ...base, charged: null, returned: null, writeoff: 0, reason: null, settledAt: null };
  if (res.status === "held") return { buildId: b.id, model, state: TERMINAL.has(b.status) ? "settling" : "running", held: res.amount, ...base, charged: null, returned: null, writeoff: 0, reason: null, settledAt: null };
  const m = (settle?.meta ?? {}) as { released?: number; writeoff?: number };
  const charged = res.charged ?? Math.max(0, -(settle?.delta ?? 0));
  return {
    buildId: b.id, model, state: res.status === "settled" ? "settled" : "released", held: res.amount, ...base, overHeld: charged > res.amount,
    charged, returned: typeof m.released === "number" ? m.released : Math.max(0, res.amount - charged), writeoff: typeof m.writeoff === "number" ? m.writeoff : 0,
    reason: settle?.note ?? null, settledAt: (res.settledAt ?? settle?.createdAt)?.toISOString() ?? null,
  };
}

async function load(userId: string, builds: Build[]): Promise<BuildSpend[]> {
  if (!builds.length) return [];
  const ids = builds.map((b) => b.id);
  const [cfg, res, settles] = await Promise.all([
    loadTokenConfig(),
    db.cyrusTokenReservation.findMany({ where: { buildId: { in: ids }, userId }, select: { buildId: true, amount: true, status: true, charged: true, model: true, settledAt: true } }),
    db.cyrusTokenLedger.findMany({ where: { userId, idemKey: { in: ids.map((i) => `settle:${i}`) } }, select: { buildId: true, delta: true, note: true, meta: true, createdAt: true } }),
  ]);
  const r = new Map(res.map((x) => [x.buildId, x]));
  const s = new Map(settles.map((x) => [x.buildId, x]));
  return builds.map((b) => buildSpendFrom(b, r.get(b.id) ?? null, s.get(b.id) ?? null, cfg));
}

/** The live meter for one of the user's builds (null = not theirs). */
export async function liveBuildSpend(userId: string, buildId: string): Promise<BuildSpend | null> {
  const b = await db.modBuild.findUnique({ where: { id: buildId }, select: { id: true, userId: true, status: true, costUsd: true, cyrus: true, result: true, createdAt: true } });
  if (!b || b.userId !== userId) return null;
  return (await load(userId, [b]))[0];
}

export type SpendRow = BuildSpend & { seq: number; kind: "first build" | "change" | "asset" | "import" | "revert"; label: string; status: string; createdAt: string };
export type ModSpend = {
  rootId: string;
  rows: SpendRow[];
