export function complexityOf(text: string): Complexity {
  return estimate(text, "saka").complexity;
}

export function reserveRange(model: CyrusModelId, complexity: Complexity, cfg: TokenConfig): [number, number] {
  return cfg.reserve[model]?.[complexity] ?? cfg.reserve.saka.standard;
}

/**
 * Live-test fix (C1): what a build HOLDS. The reserve table's range, raised to the planned estimate in tokens
 * (lib/cyrus/planner/estimate.ts, +20% headroom on the high end) so the real spend rarely exceeds the hold: the first
 * live Yakko build held 250 (the table's simple high) and spent 431. Without an estimate: the table, unchanged.
 */
export function holdRange(model: CyrusModelId, complexity: Complexity, cfg: TokenConfig, usd?: readonly [number, number]): [number, number] {
  const t = reserveRange(model, complexity, cfg);
  if (!usd) return t;
  const lo = tokensForCost(usd[0], model, cfg);
  const hi = Math.ceil(tokensForCost(usd[1], model, cfg) * 1.2);
  return [Math.max(t[0], lo), Math.max(t[1], hi, lo)];
}

/** Pre-build estimate shown in the composer: the [typical, high] token range. */
export function estimateTokens(text: string, model: CyrusModelId, cfg: TokenConfig): { complexity: Complexity; low: number; high: number } {
  const complexity = complexityOf(text);
  const [low, high] = reserveRange(model, complexity, cfg);
  return { complexity, low, high };
}

/**
 * How much to hold for a build: the high end of the range, or everything the account has
 * when that is less but still covers the typical cost. null = not enough to start.
 */
export function reserveAmount(available: number, range: [number, number]): number | null {
  if (available >= range[1]) return range[1];
  if (available >= range[0]) return available;
  return null;
}

