// Plans
// ---------------------------------------------------------------------------

/**
 * Tokens for one paid plan invoice.
 *  - subscription_create / subscription_cycle: the tier's full monthly amount (they stack).
 *  - subscription_update (an upgrade's proration): tokens in proportion to the money collected,
 *    at the new tier's rate, never more than one month of the new tier.
 */
export function planInvoiceTokens(i: { billingReason: string | null; amountPaidCents: number; tier: PlanTier; priceCents?: number | null }, cfg: TokenConfig): number {
  if (!(i.amountPaidCents > 0)) return 0;
  const monthly = cfg.plan.tokens[i.tier];
  if (i.billingReason === "subscription_create" || i.billingReason === "subscription_cycle") return monthly;
  // The proration rate is the plan's REAL Stripe price when known (the Setting is the fallback).
  const price = i.priceCents && i.priceCents > 0 ? i.priceCents : cfg.plan.cents[i.tier];
  if (i.billingReason === "subscription_update") return Math.min(monthly, Math.round((i.amountPaidCents / price) * monthly));
  return 0;
}

/** A plan month's tokens expire `rolloverMonths` months (31-day months) after they were granted. */
export function planLotExpiry(grantedAt: Date, cfg: TokenConfig): Date {
  return new Date(grantedAt.getTime() + Math.round(cfg.plan.rolloverMonths * 31) * DAY);
}

export function topupTokens(cents: number, cfg: TokenConfig): number {
  return Math.floor((cents / 100) * cfg.topup.tokensPerUsd);
}

export function validTopupCents(cents: number, cfg: TokenConfig): boolean {
  return Number.isInteger(cents) && cents >= cfg.topup.minCents && cents <= cfg.topup.maxCents;
}

/** Plan tier of a Stripe price lookup key: cyrus_plan_<tier>_v1. */
export const PLAN_LOOKUP_KEY = (tier: PlanTier) => `cyrus_plan_${tier}_v1`;
export function tierFromLookupKey(k: string | null | undefined): PlanTier | null {
  const m = /^cyrus_plan_(katara|saka|all)_v\d+$/.exec(k || "");
  return m ? (m[1] as PlanTier) : null;
}

/** Recommended worst-case margin per plan (all tokens burnt at multiplier 1, Stripe 2.9% + 30c). */
export function planMargin(tier: PlanTier, cfg: TokenConfig): { priceUsd: number; aiCostUsd: number; stripeFeeUsd: number; marginUsd: number; marginPct: number } {
  const priceUsd = cfg.plan.cents[tier] / 100;
  const aiCostUsd = cfg.plan.tokens[tier] / cfg.tokensPerUsd;
  const stripeFeeUsd = priceUsd * 0.029 + 0.3;
  const marginUsd = priceUsd - aiCostUsd - stripeFeeUsd;
  return { priceUsd, aiCostUsd, stripeFeeUsd, marginUsd, marginPct: priceUsd ? marginUsd / priceUsd : 0 };
}

"use strict";
// Per-call and per-stage usage accounting for the Mod Builder (service 0.5+).
// Pure (no I/O), unit-tested in test/modbuilder-efficiency.test.ts.
//
// The Claude CLI's stream-json output carries one `assistant` message per content
// block, all sharing the API message id and the same `usage`. A "turn" is one API
// request = one unique message id. Per turn we keep the four usage counters and the
// tools the model called, so an analysis can see exactly what each turn re-read
// (cache_read), what it added to the cache (cache_creation) and what it generated
// (output, which includes the model's thinking).
//
// Records written (all additive; the portal reads only the fields it already knew):
//   aiCalls[i].tokens     {input, cacheRead, output}  (unchanged meaning: input = all input incl. cache)
//                         + {uncached, cacheWrite}
//   aiCalls[i].turnsDetail  [[uncached, cacheWrite, cacheRead, output, toolCount, "Write,Write"], ...] (max 80)
//   aiCalls[i].toolCalls  {Write: 4, Read: 1, ...}
//   aiCalls[i].apiMs      time the API spent answering (result.duration_api_ms)
//   aiCalls[i].explore    true when the first turn only looked around (Glob/Grep/Read, no write)
//   usage                 {stages: {<stage>: {n, ms, costUsd, turns, input, cacheWrite, cacheRead, output, toolCalls}}, autofix, savedRepairs}

const MAX_TURN_ROWS = 80;

function newMeter() {
  return { ids: new Set(), order: [], turns: new Map(), tools: {}, result: null };
}

/** Feed every parsed stream-json line here. */
function onMessage(meter, msg) {
  if (!msg || typeof msg !== "object") return;
  if (msg.type === "assistant" && msg.message) {
    const m = msg.message;
    const id = m.id || `anon-${meter.order.length}`;
    if (!meter.turns.has(id)) {
      meter.turns.set(id, { usage: null, tools: [] });
      meter.order.push(id);
    }
    const t = meter.turns.get(id);
    if (m.usage) t.usage = m.usage; // identical on every block of the message; keep the latest
    for (const c of Array.isArray(m.content) ? m.content : []) {
      if (c && c.type === "tool_use" && c.id && !meter.ids.has(c.id)) {
        meter.ids.add(c.id);
        t.tools.push(c.name);
        meter.tools[c.name] = (meter.tools[c.name] || 0) + 1;
      }
    }
  } else if (msg.type === "result") meter.result = msg;
}

function n(x) { return typeof x === "number" && Number.isFinite(x) ? x : 0; }

/** Summary of one CLI call. Prefers the result's own totals; falls back to the per-turn sum. */
function summarize(meter) {
  const rows = meter.order.map((id) => {
    const t = meter.turns.get(id);
    const u = t.usage || {};
    return [n(u.input_tokens), n(u.cache_creation_input_tokens), n(u.cache_read_input_tokens), n(u.output_tokens), t.tools.length, t.tools.join(",")];
  });
  const sum = rows.reduce((a, r) => { a[0] += r[0]; a[1] += r[1]; a[2] += r[2]; a[3] += r[3]; return a; }, [0, 0, 0, 0]);
  const ru = meter.result && meter.result.usage ? meter.result.usage : null;
  const uncached = ru ? n(ru.input_tokens) : sum[0];
  const cacheWrite = ru ? n(ru.cache_creation_input_tokens) : sum[1];
  const cacheRead = ru ? n(ru.cache_read_input_tokens) : sum[2];
  const output = ru ? n(ru.output_tokens) : sum[3];
  const first = rows[0];
  const explore = !!first && first[4] > 0 && first[5].split(",").every((x) => x === "Glob" || x === "Grep" || x === "Read" || x === "LS");
  return {
    tokens: { input: uncached + cacheWrite + cacheRead, cacheRead, output, uncached, cacheWrite },
    turnsDetail: rows.slice(0, MAX_TURN_ROWS),
    toolCalls: { ...meter.tools },
    apiMs: meter.result ? n(meter.result.duration_api_ms) || null : null,
    explore,
  };
}

// ------------------------------------------------------------- stages ----
function stage(rec, name) {
  if (!rec.usage || typeof rec.usage !== "object") rec.usage = { stages: {}, autofix: 0, savedRepairs: 0 };
  if (!rec.usage.stages[name]) rec.usage.stages[name] = { n: 0, ms: 0 };
  return rec.usage.stages[name];
}

}
/** Wall time of a non-AI stage (validate, precheck, compile, scan, autofix, reuse). */
function addTime(rec, name, ms) {
  const s = stage(rec, name);
  s.n += 1;
  s.ms += Math.max(0, Math.round(ms));
}
/** One AI call into its stage (classify / generate / change / repair / repair-safety). */
function addCall(rec, call) {
  const s = stage(rec, call.kind || "generate");
  s.n += 1;
  s.ms += n(call.durationMs);
  s.costUsd = +((s.costUsd || 0) + n(call.costUsd)).toFixed(4);
  s.turns = (s.turns || 0) + n(call.turns);
  const t = call.tokens || {};
  for (const k of ["input", "cacheWrite", "cacheRead", "output"]) s[k] = (s[k] || 0) + n(t[k]);
  if (call.toolCalls) {
    s.toolCalls = s.toolCalls || {};
    for (const [k, v] of Object.entries(call.toolCalls)) s.toolCalls[k] = (s.toolCalls[k] || 0) + v;
  }
}

// ------------------------------------------------------------ pricing ----
// USD per million tokens, Anthropic list prices (2026-09). cacheWrite depends on the TTL:
// 5 min = 1.25 x input, 1 h = 2 x input; cacheRead = 0.1 x input. Used only for the
// offline analysis and the cost model; the service bills on the CLI's own total_cost_usd.
const PRICES = {
  "claude-haiku-4-5": { in: 1, out: 5 },
  "claude-sonnet-5": { in: 2, out: 10 },
  "claude-sonnet-5-5": { in: 2, out: 10 },
  "claude-opus-5": { in: 5, out: 25 },
  "claude-opus-5-5": { in: 4, out: 20 },
};
function priceOf(model) {
  const m = String(model || "").replace(/-\d{8}$/, "");
  if (PRICES[m]) return PRICES[m];
  if (/haiku/.test(m)) return PRICES["claude-haiku-4-5"];
  if (/opus-5-5/.test(m)) return PRICES["claude-opus-5-5"];
  if (/opus/.test(m)) return PRICES["claude-opus-5"];
  return PRICES["claude-sonnet-5-5"];
}
/** Split a call's cost into its parts. ttl: "5m" | "1h". */
function costParts(tokens, model, ttl = "1h") {
  const p = priceOf(model);
  const w = ttl === "5m" ? 1.25 : 2;
  const t = tokens || {};
  const uncached = n(t.uncached != null ? t.uncached : 0);
  const cacheWrite = n(t.cacheWrite != null ? t.cacheWrite : Math.max(0, n(t.input) - n(t.cacheRead) - uncached));
  const parts = {
    uncached: (uncached * p.in) / 1e6,
    cacheWrite: (cacheWrite * p.in * w) / 1e6,
    cacheRead: (n(t.cacheRead) * p.in * 0.1) / 1e6,
    output: (n(t.output) * p.out) / 1e6,
  };
  parts.total = parts.uncached + parts.cacheWrite + parts.cacheRead + parts.output;
  return parts;
}

// ------------------------------------------------------------ live (B) ----
/**
 * Cyrus live-test fix (B): the running cost of ONE CLI call while it streams, so the portal's token meter moves during
 * planning and coding (the call's real total_cost_usd only arrives when the CLI exits; the first live test showed the
 * meter stuck at the guard's 5 tokens for 3 minutes). Finished turns use their reported usage; the turn in flight uses
 * its message_start usage plus its streamed characters / 4 as output. An ESTIMATE: billing still uses total_cost_usd.
 * partials: Map<messageId, { input, cacheWrite, cacheRead, chars, out }> from the stream events.
 */
function liveCallCost(meter, model, partials, ttl = "1h") {
  let usd = 0, output = 0;
  const seen = new Set();
  const add = (u, extraChars, id) => {
    const est = Math.round(n(extraChars) / 4);
    const t = { uncached: n(u.input_tokens), cacheWrite: n(u.cache_creation_input_tokens), cacheRead: n(u.cache_read_input_tokens), output: Math.max(n(u.output_tokens), est) };
    usd += costParts(t, model, ttl).total; output += t.output; seen.add(id);
  };
  for (const id of meter.order) {
    const u = meter.turns.get(id).usage;
    const p = partials && partials.get(id);
    if (u || p) add({ ...(p ? { input_tokens: p.input, cache_creation_input_tokens: p.cacheWrite, cache_read_input_tokens: p.cacheRead, output_tokens: p.out } : {}), ...(u || {}), output_tokens: Math.max(n(u && u.output_tokens), n(p && p.out)) }, p ?
  }
  if (partials) for (const [id, p] of partials) if (!seen.has(id)) add({ input_tokens: p.input, cache_creation_input_tokens: p.cacheWrite, cache_read_input_tokens: p.cacheRead, output_tokens: p.out }, p.chars, id);
  return { usd: +usd.toFixed(4), output, turns: seen.size };
}

// ------------------------------------------------------------- dedupe ----
/** Same request -> same key (whitespace-insensitive request text; everything else exact). */
function dedupeKey({ promptVersion, knowledge, mcVersion, pluginName, tier, model, prompt, extra }) {
  const text = String(prompt || "").replace(/\s+/g, " ").trim();
  return require("crypto").createHash("sha256")
    .update(JSON.stringify([promptVersion || "", knowledge || "", mcVersion || "", pluginName || "", tier || "", model || "", text, extra == null ? null : extra]))
    .digest("hex").slice(0, 32);
}

module.exports = { dedupeKey, newMeter, onMessage, summarize, addTime, addCall, PRICES, priceOf, costParts, liveCallCost, MAX_TURN_ROWS };
