/** issuedAt: milliseconds since the epoch (Date.now()) when the panel issued the token. */
export type GatewayTokenClaims = { serverId: string; modId: string; issuedAt: number };

/** r40 (AC O-2): tokens expire. Default 30 days (setting cyrus_ai_gw_token_max_age_days, 1..365); the panel re-issues. */
export const GATEWAY_TOKEN_DEFAULT_MAX_AGE_DAYS = 30;
const FUTURE_SKEW_MS = 5 * 60_000;

/**
 * Per-server, per-mod token the Nxeon panel places on the customer's server (never in the
 * mod's jar or source). Stateless HMAC for the stub; the real gateway should store a hash so a
 * token can be revoked on its own (AI-GATEWAY.md "Tokens").
 */
export function issueGatewayToken(c: GatewayTokenClaims): string {
  const payload = b64u(JSON.stringify({ s: c.serverId, m: c.modId, iat: c.issuedAt }));
  const sig = b64u(createHmac("sha256", key()).update(`${TOKEN_PREFIX}.${payload}`).digest());
  return `${TOKEN_PREFIX}.${payload}.${sig}`;
}

export function verifyGatewayToken(token: string | null | undefined, opts: { nowMs?: number; maxAgeMs?: number } = {}): GatewayTokenClaims | null {
  const nowMs = opts.nowMs ?? Date.now();
  const maxAgeMs = opts.maxAgeMs ?? GATEWAY_TOKEN_DEFAULT_MAX_AGE_DAYS * 86_400_000;
  const parts = String(token || "").split(".");
  if (parts.length !== 3 || parts[0] !== TOKEN_PREFIX) return null;
  const want = createHmac("sha256", key()).update(`${parts[0]}.${parts[1]}`).digest();
  const got = Buffer.from(parts[2], "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) return null;
  try {
    const p = JSON.parse(Buffer.from(parts[1], "base64url").toString("utf8")) as { s?: unknown; m?: unknown; iat?: unknown };
    if (typeof p.s !== "string" || typeof p.m !== "string" || typeof p.iat !== "number" || !Number.isFinite(p.iat)) return null;
    // expired, or issued in the future (clock abuse): refused
    if (p.iat > nowMs + FUTURE_SKEW_MS || nowMs - p.iat > maxAgeMs) return null;
    return { serverId: p.s, modId: p.m, issuedAt: p.iat };
  } catch { return null; }
}

/** The token max age from settings (days, clamped 1..365; a bad value is the default). */
export async function gatewayTokenMaxAgeMs(): Promise<number> {
  const d = parseInt((await getHost().settings.get("cyrus_ai_gw_token_max_age_days", String(GATEWAY_TOKEN_DEFAULT_MAX_AGE_DAYS)).catch(() => "")) || "", 10);
  return (Number.isFinite(d) && d >= 1 && d <= 365 ? d : GATEWAY_TOKEN_DEFAULT_MAX_AGE_DAYS) * 86_400_000;
}

